style.css:
@-moz-document domain("amocrm.ru") {
/* 1) Токены (Notion-ish) */
  :root{
    --n-bg0: #0f1115;
    --n-bg1: #141824;
    --n-surface: #191f2e;
    --n-surface-2: #1e2638;

    --n-border: #2a3347;
    --n-border-2: #323d55;

    --n-text: #e7eaf0;
    --n-text-2: #aab2c5;
    --n-text-3: #7f8aa6;

    --n-accent: #4f8cff;
    --n-accent-2: #7aa7ff;

    --n-danger: #ff5c7a;
    --n-success: #39d98a;
    --n-warn: #ffb020;

    --n-radius: 10px;
    --n-shadow: 0 10px 30px rgba(0,0,0,.35);
  }

  /* 2) Переопределение палитры amoCRM (работает лучше, чем точечные классы) */
  html[data-color-scheme="dark"],
  html[data-color-scheme="dark"] :root,
  :root[data-color-scheme="dark"] {
    /* Эти имена переменных встречаются в документации/примерах amoCRM */
    --palette-background-primary: var(--n-bg0) !important;
    --palette-background-secondary: var(--n-bg1) !important;

    --palette-border-default: var(--n-border) !important;

    --palette-text-primary: var(--n-text) !important;
    --palette-text-secondary: var(--n-text-2) !important;
    --palette-text-secondary-dark: var(--n-text-2) !important;

    --palette-primary: var(--n-accent) !important;
  }

  /* 3) База */
  html, body {
    background-color: var(--n-bg0) !important;
    color: var(--n-text) !important;
  }

  a, a:visited { color: var(--n-accent-2) !important; }
  a:hover { color: var(--n-accent) !important; }

  /* 4) Поверхности/контейнеры (обобщённо, чтобы покрыть больше интерфейса) */
  [class*="card"],
  [class*="Card"],
  [class*="panel"],
  [class*="Panel"],
  [class*="widget"],
  [class*="Widget"],
  [class*="container"],
  [class*="Container"],
  [class*="modal"],
  [class*="Modal"],
  [class*="popup"],
  [class*="Popup"]{
    background: var(--n-surface) !important;
    color: var(--n-text) !important;
    border-color: var(--n-border) !important;
  }

  /* 5) Инпуты */
  input, textarea, select {
    background: var(--n-bg1) !important;
    color: var(--n-text) !important;
    border: 1px solid var(--n-border) !important;
    border-radius: var(--n-radius) !important;
    outline: none !important;
  }
  input::placeholder, textarea::placeholder {
    color: var(--n-text-3) !important;
  }
  input:focus, textarea:focus, select:focus {
    border-color: rgba(79,140,255,.65) !important;
    box-shadow: 0 0 0 3px rgba(79,140,255,.18) !important;
  }

  /* 6) Кнопки (очень обобщённо) */
  button, [role="button"], .button, [class*="btn"], [class*="Button"]{
    background: var(--n-surface-2) !important;
    color: var(--n-text) !important;
    border: 1px solid var(--n-border) !important;
    border-radius: var(--n-radius) !important;
  }
  button:hover, [role="button"]:hover, .button:hover, [class*="btn"]:hover, [class*="Button"]:hover{
    border-color: var(--n-border-2) !important;
    background: #232c42 !important;
  }

  /* 7) Таблицы/списки */
  table, [class*="table"], [class*="Table"]{
    color: var(--n-text) !important;
  }
  tr:hover, [class*="row"]:hover, [class*="Row"]:hover{
    background: rgba(79,140,255,.10) !important;
  }

  /* 8) Разделители */
  hr, [class*="divider"], [class*="Divider"]{
    border-color: var(--n-border) !important;
    background-color: var(--n-border) !important;
  }

  /* 9) Скроллбар (Chromium) */
  *::-webkit-scrollbar { width: 12px; height: 12px; }
  *::-webkit-scrollbar-track { background: var(--n-bg0); }
  *::-webkit-scrollbar-thumb {
    background: #2a3550;
    border: 3px solid var(--n-bg0);
    border-radius: 999px;

  }

  html, body { 
  	outline: 5px solid red !important;
	}

  *::-webkit-scrollbar-thumb:hover { background: #344160; }
}
